const num=v=>Number.isFinite(Number(v))?Number(v).toLocaleString('zh-CN'):'—';
function bytes(v){if(v==null)return '—';const units=['B','KiB','MiB','GiB','TiB'];let n=Number(v),i=0;while(n>=1024&&i<4){n/=1024;i++;}return `${n.toFixed(i?1:0)} ${units[i]}`;}
function date(v){if(!v)return '—';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v));}
const labels={overview:'工作台概览',datasets:'数据集管理',import:'文件导入',jobs:'导入任务',query:'数据查询',extract:'数据提取',settings:'系统设置'};
const statusNames={queued:'排队中',importing:'写入数据',indexing:'建立索引',verifying:'校验数据',warming:'准备缓存',paused:'已暂停',cancelled:'已取消',failed:'导入失败',completed:'已完成'};
const activeStatuses=['queued','importing','indexing','verifying','warming'];
const blankFilter=()=>({field:'',op:'eq',value:''});
let authGeneration=0,previewGeneration=0;
const fileFormat=()=>((state.file?.name||state.upload?.filename||'').split('.').pop()||'csv').toLowerCase();
const fileLimit=()=>fileFormat()==='xls'?(state.stats?.max_xls_bytes||128*1024**2):(state.stats?.max_upload_bytes||20*1024**3);
let savedUpload;try{savedUpload=JSON.parse(sessionStorage.getItem('csvhub.upload')||'null');}catch{}
const state={view:'overview',user:null,token:sessionStorage.getItem('csvhub.token')||'',online:false,datasets:[],jobs:[],details:new Map(),stats:null,search:'',jobSearch:'',file:null,upload:savedUpload,uploadPhase:'idle',uploadProgress:0,uploadBusy:false,preview:null,mapping:[],target:'',datasetName:'',sheet:null,previewBusy:false,encoding:'utf-8-sig',delimiter:',',onError:'fail',rowMode:'standard',uploadController:null,hashWorker:null,queryDataset:'',filters:[blankFilter()],result:null,querySnapshot:null,pageCursors:[null],page:0,queryDirty:false,queryBusy:false,refreshing:null,jobBusy:new Set()};
function toast(message,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;while($('#toasts').children.length>=3)$('#toasts').firstElementChild.remove();$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
const friendly={'Administrator permission required':'这个操作需要管理员权限。','Login required or session expired':'登录已失效，请重新登录。','Incorrect username or password':'用户名或密码不正确。','Username already exists':'这个用户名已存在，请换一个名称。','Too many login attempts; retry in one minute':'登录次数过多，请一分钟后重试。','Login capacity is busy; retry shortly':'账号操作正在处理中，请稍后重试。','All records have been extracted':'当前版本的数据已全部提取。','Annotation changed in another window; reload the batch':'这条记录已在其他窗口修改，请刷新批次后重试。','Record exceeds interactive response size limit':'这条记录超过页面容量，无法提取。','Extraction capacity is busy; retry later':'提取任务较多，请稍后重试。','Supported file formats: CSV, XLS and XLSX':'支持 CSV、XLS 和 XLSX 文件。','Selected Excel worksheet does not exist':'所选工作表不存在，请重新选择。','Excel workbook is invalid, encrypted or unsupported':'Excel 文件无法读取，请检查格式或移除打开密码。','Excel formula has no saved result':'公式缺少已保存的计算结果','Excel cell contains an error':'Excel 单元格包含错误','Excel header contains duplicate names':'Excel 首行有重复列名。','Excel first row must contain 1 to 1024 column names':'Excel 首行需要包含 1～1024 个列名。','Excel column names must be non-empty text of at most 200 characters':'Excel 列名不能为空，且不能超过 200 个字符。','Excel shared strings/styles exceed configured metadata limit; use CSV':'Excel 字符串或样式元数据超过限制，请转换为 CSV。','An Excel preview is already running; retry shortly':'另一个 Excel 预览正在运行，请稍后重新预览。',"Dataset already has an active or paused import":"这个数据集已有活动任务，请先处理该任务。","Dataset has no published version":"数据集还没有完成导入，请等待任务完成。","CSV parsing failed; check format, encoding and record size":"文件预览失败，请检查编码、分隔符和 CSV 格式。","Not enough disk space for upload":"可用磁盘空间不足，无法上传这个文件。","Upload exceeds configured file size limit":"文件超出了当前单文件大小限制。","Cursor belongs to an older dataset version; restart query":"数据集已有新版本，请重新查询。","Query exceeded time budget; use more selective filters":"查询用时过长，请缩小筛选范围。","Filter requires an indexed column":"这个字段没有索引，请选择已建立索引的字段。","Whole-file SHA256 mismatch":"文件校验不一致，请重新上传。","Required field is empty":"必填字段为空。","Invalid filter value for configured column type":"筛选值的格式不正确，请检查日期或整数格式。"};
Object.assign(friendly,{'Only completed, failed or cancelled tasks can be deleted':'只能删除已完成、失败或已取消的任务；请先取消进行中的任务。','Cancel or finish all imports before deleting the dataset':'该数据集还有进行中或暂停的导入，请先取消或等待完成。','Dataset is in use; retry shortly':'该数据集正在被查询、提取或删除，请稍后重试。','Local files are in use; deletion was not completed':'本地文件被占用，删除未完成，请关闭占用文件的软件后重试。','Local file path is not safe to delete':'本地文件位置异常，系统已停止删除，请检查数据目录。','Another process is using this resource':'文件正在被导入或预览使用，请稍后重试。','Dataset not found':'数据集已不存在，请刷新页面。','Job not found':'导入任务已不存在，请刷新页面。','Upload not found':'原始上传文件已清理，请重新上传后再导入。'});
function errorText(detail,recordOnly=false){
  if(Array.isArray(detail))return detail.map(x=>x.msg).join('；');
  if(detail==='Error')return 'CSV 解析失败。旧版任务只保存了通用错误，无法确定具体类型和位置；这与已跳过的记录错误不同。';
  if(detail==='UnicodeDecodeError')return '文件无法按所选编码读取，请核对 CSV 编码。编码错误不属于可直接跳过的记录错误。';
  if(detail==='Column count differs from header')return '该记录的列数与表头不一致（缺列或多列）。';
  const parsed=/^CSV parse error: ([a-z_]+); record (\d+); physical lines (\d+)-(\d+)(?:; configured size limit exceeded)?$/.exec(detail||'');
  if(parsed){
    const reasons={unexpected_eof:'带引号的字段未正常结束',invalid_after_quote:'结束引号后出现不符合 CSV 格式的字符',field_too_large:'单个字段超过大小限制',record_too_large:'单条记录超过大小限制',unexpected_newline:'字段中的换行不符合 CSV 格式',invalid_csv:'文件结构不符合 CSV 格式'};
    const record=parsed[2]==='0'?'表头':`来源第 ${num(parsed[2])} 条记录`;
    const lines=parsed[3]===parsed[4]?`文件第 ${num(parsed[3])} 行`:`文件第 ${num(parsed[3])}～${num(parsed[4])} 行`;
    return `CSV 解析失败：${reasons[parsed[1]]||reasons.invalid_csv}。${record}，${lines}。${recordOnly?'该行未通过格式校验。':'记录边界或大小无法安全处理，导入已停止。'}`;
  }
  return friendly[detail]||detail||'操作失败，请稍后重试。';
}
async function api(path,{json,...options}={}){
  if(!state.token){openLogin();throw new Error('请先连接服务。');}
  const requestToken=state.token, generation=authGeneration;
  const headers={'Authorization':`Bearer ${requestToken}`,...options.headers};
  if(json!==undefined){headers['Content-Type']='application/json';options.body=JSON.stringify(json);}
  let response;try{response=await fetch('/api/v1'+path,{...options,headers});}catch(error){if(error.name==='AbortError')throw error;if(generation!==authGeneration)throw new DOMException('Session changed','AbortError');state.online=false;updateChrome();throw new Error('无法连接本地服务，请确认项目正在运行。');}
  let data;try{data=await response.json();}catch{throw new Error('服务返回了无法识别的响应。');}
  if(generation!==authGeneration||requestToken!==state.token)throw new DOMException('Session changed','AbortError');
  if(!response.ok){const error=new Error(errorText(data.detail));error.status=response.status;if(response.status===401)openLogin('登录已失效，请重新登录。');throw error;}
  state.online=true;return data;
}
function shell(){
  $('#app').innerHTML=`<div class="app"><aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><span><strong>CSVHub</strong><small>DATA WORKSPACE</small></span></a><div class="workspace">${icon('database')}<div>本地工作空间<small>LOCAL WORKSPACE</small></div><span>⌄</span></div><div class="nav-caption">数据管理</div><nav class="nav">${['overview','datasets','import','extract','query','jobs'].map((v,i)=>`<a href="#${v}" data-nav="${v}">${icon(['grid','database','upload','rows','search','clock'][i])}<span>${labels[v]}</span>${v==='jobs'?'<span class="count hidden" id="job-count"></span>':''}</a>`).join('')}</nav><div class="nav-caption" id="admin-caption" style="margin-top:29px">系统管理</div><nav class="nav"><a href="#settings" data-nav="settings">${icon('settings')}<span>系统设置</span></a></nav><div class="sidebar-bottom"><button class="btn logout-button hidden" id="account-exit" data-action="disconnect">退出登录</button><div class="local-note">${icon('shield')} 数据保存在本机</div><button class="account" data-action="login"><span class="avatar">C</span><span><strong id="account-title">连接本地服务</strong><small id="account-subtitle">输入访问令牌</small></span>${icon('chevron')}</button></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="展开导航">${icon('menu')}</button><div class="crumb"><span>工作空间</span><span>/</span><strong id="crumb-title"></strong></div><div class="top-actions"><span class="status-dot" id="connection-state"><i class="dot off"></i>未连接</span><a href="/docs" target="_blank" rel="noopener"><span class="docs-label">接口文档</span>${icon('external')}</a></div></header><div class="content" id="content"></div></main></div>`;
  setView(location.hash.slice(1)||'overview',false);
}
function updateChrome(){
  if(!$('#connection-state'))return;
  $('#connection-state').innerHTML=`<i class="dot ${state.online&&state.token?'':'off'}"></i>${state.online&&state.token?'服务已连接':state.token?'连接中断':'未连接'}`;
  $('#account-title').textContent=state.user?.username||'连接本地服务';$('#account-subtitle').textContent=state.user?(state.user.role==='admin'?'管理员':'普通用户'):'账号登录';const limited=state.token&&state.user?.role!=='admin';for(const v of ['datasets','import','jobs','settings'])document.querySelector(`[data-nav="${v}"]`).classList.toggle('hidden',Boolean(limited));$('#admin-caption').classList.toggle('hidden',Boolean(limited));document.querySelector('.top-actions a').classList.toggle('hidden',Boolean(limited));$('#account-exit').classList.toggle('hidden',!state.token);
  const count=state.jobs.filter(j=>activeStatuses.includes(j.status)).length;$('#job-count').textContent=count;$('#job-count').classList.toggle('hidden',!count);
}
function setView(view,hash=true){state.view=labels[view]&&!(state.user?.role==='user'&&!['overview','extract','query'].includes(view))?view:'overview';if(hash&&location.hash!=='#'+state.view)location.hash=state.view;if(!state.token||!state.user||!$('#content'))return;for(const el of document.querySelectorAll('[data-nav]'))el.classList.toggle('active',el.dataset.nav===state.view);$('#crumb-title').textContent=labels[state.view];$('.app').classList.remove('menu-open');render();}
function header(title,subtitle,actions='',eyebrow='LOCAL DATA / 工作空间'){return `<div class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
const primaryImport=`<button class="btn primary" data-action="new-import">${icon('plus')} 导入文件</button>`;
const empty=(title,copy,button='',symbol='database')=>`<div class="empty"><div class="empty-icon">${icon(symbol)}</div><h3>${title}</h3><p>${copy}</p>${button}</div>`;
function guard(copy='连接本地服务后，即可管理你的数据集。'){return empty('连接服务，开始管理数据',copy,'<button class="btn primary" data-action="login">'+icon('lock')+' 连接本地服务</button>','lock');}
function datasetRows(items){return items.map(d=>{const detail=state.details.get(d.id),version=detail?.version,busy=state.jobs.some(j=>j.dataset_id===d.id&&(activeStatuses.includes(j.status)||j.status==='paused'));return `<tr><td><div class="dataset-cell"><span class="file-badge">${icon('file')}</span><span><strong>${esc(d.name)}</strong><small>${esc(d.id.slice(0,8))} · ${d.columns.length} 个字段</small></span></div></td><td>${version?num(version.accepted):'—'}</td><td>${version?'<span class="pill"><i class="dot"></i>可查询</span>':'<span class="pill neutral">等待导入</span>'}</td><td>${date(version?.published_at||d.created_at)}</td><td><div class="actions"><button class="btn ghost sm" data-action="dataset-query" data-id="${d.id}" ${version?'':'disabled'}>查询</button><button class="btn ghost sm" data-action="dataset-import" data-id="${d.id}">导入</button><button class="btn ghost sm" data-action="versions" data-id="${d.id}" aria-label="查看版本">${icon('clock')}</button>${state.user?.role==='admin'?`<button class="btn ghost sm danger" data-action="dataset-delete" data-id="${d.id}" ${busy?'disabled':''} title="${busy?'请先取消或完成该数据集的导入任务':'删除数据集及本系统保存的原始上传文件'}">删除</button>`:''}</div></td></tr>`;}).join('');}
function datasetTable(items){if(!state.token)return guard();if(!items.length)return empty('这里还没有数据集','从 CSV 或 Excel 文件开始。导入完成后，就能在这里查看与查询数据。',primaryImport);return `<div class="table-wrap"><table class="data-table"><thead><tr><th>数据集</th><th>已发布记录</th><th>状态</th><th>最近更新</th><th>操作</th></tr></thead><tbody>${datasetRows(items)}</tbody></table></div>`;}
function badge(job){let cls=job.status==='failed'?'error':['paused','queued'].includes(job.status)?'warning':job.status==='cancelled'?'neutral':'';return `<span class="pill ${cls}">${job.cancel_requested&&activeStatuses.includes(job.status)?'取消中':job.pause_requested&&activeStatuses.includes(job.status)?'暂停中':statusNames[job.status]||esc(job.status)}</span>`;}
function metric(label,value,unit,caption,symbol){return `<div class="metric"><div class="label">${label}${icon(symbol)}</div><span class="number">${value}</span><span class="unit">${unit}</span><small>${caption}</small></div>`;}
function overview(){if(state.user?.role==='user')return workbench.userOverview();const total=state.datasets.reduce((n,d)=>n+(state.details.get(d.id)?.version?.accepted||0),0);return header('数据工作台','管理导入、追踪任务，让每一份数据都井然有序。',primaryImport)+`<section class="hero"><div><div class="hero-label">${icon('shield')} YOUR DATA, YOUR WORKSPACE</div><h2>把大文件，变成可查询的数据。</h2><p>分块上传、后台导入、建立索引。<br>从文件到查询，在一个工作空间里完成。</p><a class="btn sm" href="/assets/example.csv" download>${icon('download')} 下载示例文件</a></div><div class="hero-flow"><div class="flow-node">${icon('file')}CSV / Excel</div><span class="flow-arrow">→</span><div class="flow-node">${icon('database')}建立索引</div><span class="flow-arrow">→</span><div class="flow-node">${icon('search')}快速查询</div></div></section><section class="metrics">${metric('已加载数据集',state.token?num(state.datasets.length):'—','个','当前工作空间列表','database')}${metric('已发布记录',state.token?num(total):'—','条','当前列表中的已发布版本','rows')}${metric('进行中的任务',state.token?num(state.jobs.filter(j=>activeStatuses.includes(j.status)).length):'—','个','最近任务列表','clock')}${metric('可用磁盘',state.stats?bytes(state.stats.free_disk_bytes).split(' ')[0]:'—',state.stats?bytes(state.stats.free_disk_bytes).split(' ')[1]:'','数据存储所在磁盘','database')}</section>${workbench.adminOverviewPanel()}<div class="section-title"><h2>最近的数据集 <span class="sub">从这里继续工作</span></h2><a href="#datasets">全部数据集 ${icon('arrow')}</a></div><section class="panel">${datasetTable(state.datasets.slice(0,5))}</section><div class="overview-bottom"><section class="panel"><div class="panel-head"><span>最近导入</span><a href="#jobs" class="muted">查看全部 →</a></div>${state.token&&state.jobs.length?state.jobs.slice(0,3).map(j=>`<div class="small-job"><span class="job-symbol">${icon(j.status==='completed'?'check':'clock')}</span><div class="details"><strong>${esc(jobName(j))}</strong><small>${num(j.accepted)} 条已写入 · ${date(j.updated_at)}</small></div>${badge(j)}</div>`).join(''):empty('暂无导入记录','开始上传文件后，可在这里跟踪导入状态。','','clock')}</section><section class="panel"><div class="panel-head">从文件开始，三步完成</div><div class="guide"><div class="guide-step"><b>01</b><div><strong>上传 CSV / Excel</strong><p>分块传输，文件中断后可重新选择并续传。</p></div></div><div class="guide-step"><b>02</b><div><strong>确认字段和索引</strong><p>预览内容，选择要保留及检索的字段。</p></div></div><div class="guide-step"><b>03</b><div><strong>等待完成，开始查询</strong><p>后台完成写入、建索引和校验后发布。</p></div></div></div></section></div><div class="footnote">${icon('shield')} 本地存储 · 页面显示真实服务数据 · 时区 Asia/Shanghai</div>`;}
function datasets(){return header('数据集管理','查看已发布的数据，或为现有数据集导入新的版本。',primaryImport)+`<div class="toolbar"><div class="input-search">${icon('search')}<input class="input" id="dataset-search" placeholder="按数据集名称筛选" value="${esc(state.search)}" aria-label="筛选数据集"></div><button class="btn" data-action="refresh">${icon('refresh')} 刷新</button></div><section class="panel" id="dataset-list">${datasetTable(state.datasets.filter(d=>d.name.toLowerCase().includes(state.search.toLowerCase())))}</section>`;}
function jobName(j){return state.datasets.find(d=>d.id===j.dataset_id)?.name||'数据集 '+j.dataset_id.slice(0,8);}
function canRetryLines(j){return j.status==='failed'&&j.options.row_mode!=='single_line'&&(j.error==='Error'||/^CSV parse error: (invalid_after_quote|unexpected_eof|unexpected_newline|invalid_csv);/.test(j.error||''));}
function jobButtons(j){const busy=state.jobBusy.has(j.id)||j.pause_requested||j.cancel_requested;return `<div class="actions">${activeStatuses.includes(j.status)?`<button class="btn ghost sm" data-action="job-pause" data-id="${j.id}" ${busy?'disabled':''}>${icon('pause')}暂停</button><button class="btn ghost sm danger" data-action="job-cancel" data-id="${j.id}" ${busy?'disabled':''}>取消</button>`:j.status==='paused'?`<button class="btn ghost sm" data-action="job-resume" data-id="${j.id}">继续</button><button class="btn ghost sm danger" data-action="job-cancel" data-id="${j.id}">取消</button>`:['failed','cancelled'].includes(j.status)?`<button class="btn ghost sm" data-action="job-retry" data-id="${j.id}" ${state.jobBusy.has(j.id)?'disabled':''}>重新导入</button>`:''}${canRetryLines(j)?`<button class="btn ghost sm" data-action="job-retry-lines" data-id="${j.id}" title="仅适用于一行一条记录的 CSV；复用上传文件，跳过坏行后继续" ${busy?'disabled':''}>逐行容错重试</button>`:''}<button class="btn ghost sm" data-action="job-errors" data-id="${j.id}">详情</button>${state.user?.role==='admin'&&['completed','failed','cancelled'].includes(j.status)?`<button class="btn ghost sm danger" data-action="job-delete" data-id="${j.id}" ${state.jobBusy.has(j.id)?'disabled':''}>删除</button>`:''}</div>`;}
function jobTable(items){if(!state.token)return guard();if(!items.length)return empty('暂无导入任务','上传并确认字段后，任务会在后台运行。你可以在这里暂停、继续或查看错误。',primaryImport,'clock');return `<div class="table-wrap"><table class="data-table"><thead><tr><th>数据集 / 任务</th><th>阶段</th><th>处理记录</th><th>最近更新</th><th>操作</th></tr></thead><tbody>${items.map(j=>`<tr><td><div class="dataset-cell"><span class="file-badge">${icon('file')}</span><span><strong>${esc(jobName(j))}</strong><small>${j.id.slice(0,8)}</small></span></div></td><td>${badge(j)}</td><td class="job-progress">${num(j.accepted)} 条已写入<small>处理 ${num(j.processed)} · 拒绝 ${num(j.rejected)}</small>${activeStatuses.includes(j.status)?`<small>${bytes(j.bytes_read)} 已读取${j.status==='queued'?' · 等待执行器':''}</small>`:''}</td><td>${date(j.updated_at)}</td><td>${jobButtons(j)}</td></tr>`).join('')}</tbody></table></div>`;}
function jobs(){return header('导入任务','写入完成后，任务还会继续建立索引、校验数据并准备缓存。',`<button class="btn" data-action="refresh">${icon('refresh')} 刷新</button>`)+`<div class="toolbar"><div class="input-search">${icon('search')}<input class="input" id="job-search" placeholder="按数据集或任务编号筛选" value="${esc(state.jobSearch)}" aria-label="筛选任务"></div><span class="help">进行中的任务每 4 秒更新</span></div><section class="panel" id="job-list">${jobTable(state.jobs.filter(j=>(jobName(j)+j.id).toLowerCase().includes(state.jobSearch.toLowerCase())))}</section>`;}
function csvModeControls(){return fileFormat()!=='csv'?'':`<div style="margin-top:16px"><label class="form-label" for="csv-row-mode">CSV 记录格式</label><select id="csv-row-mode" ${state.uploadBusy||state.previewBusy?'disabled':''}><option value="standard" ${state.rowMode==='standard'?'selected':''}>标准 CSV（允许字段内换行）</option><option value="single_line" ${state.rowMode==='single_line'?'selected':''}>一行一条记录（逐行容错）</option></select><p class="help">逐行容错需同时选择“跳过错误记录”；每行独立解析，坏引号不会影响下一行。仅用于字段内没有换行的文件。</p></div>`;}
function importPage(){const stage=!state.file?0:state.uploadPhase==='ready'?2:1;return header('文件导入','从 CSV 或 Excel 文件开始，把需要的数据带入工作空间。','', 'IMPORT / 文件导入')+`<div class="steps">${['选择文件','校验与上传','配置字段','后台导入'].map((n,i)=>`<div class="step ${i===stage?'active':i<stage?'done':''}"><b>${i<stage?'✓':i+1}</b>${n}</div>`).join('')}</div><div class="import-grid"><div><section class="panel"><div class="panel-head"><span>01 / 上传数据文件</span><span class="pill neutral">分块上传</span></div><input id="file-input" type="file" accept=".csv,.xls,.xlsx,text/csv,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" class="hidden" aria-label="选择 CSV / Excel 文件">${state.file?`<div class="selected-file"><span class="file-badge">${icon('file')}</span><div class="file-details"><strong>${esc(state.file.name)}</strong><small>${bytes(state.file.size)} · ${esc(fileFormat().toUpperCase())} 文件</small></div><button class="btn ghost sm" data-action="choose-file" ${state.uploadBusy?'disabled':''}>更换</button></div>`:`<div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="选择或拖入 CSV / Excel 文件"><span class="upload-icon">${icon('upload')}</span><strong>拖入 CSV / Excel 文件，或点击选择</strong><p>支持 .csv / .xls / .xlsx · 分块传输<br>CSV / XLSX 上限 ${bytes(state.stats?.max_upload_bytes||20*1024**3)} · XLS 上限 ${bytes(state.stats?.max_xls_bytes||128*1024**2)}</p></div>`}<div class="progress-area ${state.file?'':'hidden'}"><div class="progress-header"><span id="upload-stage">${uploadPhaseLabel()}</span><span id="upload-percent">${Math.round(state.uploadProgress)}%</span></div><div class="progress-track"><div id="upload-bar" style="width:${state.uploadProgress}%"></div></div></div><div class="upload-options">${['xls','xlsx'].includes(fileFormat())?'<div class="notice info">Excel 上传完成后可选择工作表。首行作为列名，空白行会跳过；仅读取已保存的公式结果。</div>':''}<div class="form-grid ${['xls','xlsx'].includes(fileFormat())?'hidden':''}"><div><label class="form-label" for="encoding">文件编码</label><select id="encoding" ${state.uploadBusy?'disabled':''}><option value="utf-8-sig" ${state.encoding==='utf-8-sig'?'selected':''}>UTF-8（支持 BOM）</option><option value="gb18030" ${state.encoding==='gb18030'?'selected':''}>GB18030 / GBK</option><option value="utf-8" ${state.encoding==='utf-8'?'selected':''}>UTF-8（无 BOM）</option></select></div><div><label class="form-label" for="delimiter">字段分隔符</label><select id="delimiter" ${state.uploadBusy?'disabled':''}>${[[',','逗号 ,'],['\t','制表符 Tab'],[';','分号 ;'],['|','竖线 |']].map(([v,n])=>`<option value="${esc(v)}" ${state.delimiter===v?'selected':''}>${n}</option>`).join('')}</select></div></div>${csvModeControls()}${state.upload&&!state.file?'<div class="notice info">上次上传信息已保留。重新选择同一文件后，可继续未完成的上传。</div>':''}<div class="actions" style="margin-top:20px;justify-content:flex-end">${state.uploadBusy?'<button class="btn" data-action="upload-stop">暂停上传</button>':`<button class="btn primary" data-action="upload-start" ${!state.file?'disabled':''}>${icon(state.uploadPhase==='ready'?'refresh':'upload')}${state.uploadPhase==='ready'?'重新预览':state.uploadPhase==='paused'?'继续校验与上传':'校验并上传'}</button>`}</div></div></section>${state.preview?mappingPanel():''}</div><aside class="import-aside"><section class="panel"><div class="aside-copy"><h3>为大文件准备</h3><p>文件以小块进行校验与传输，不会一次装入浏览器内存。关闭页面后，已提交的导入任务仍会在后台运行。</p><div class="aside-stat"><span>单文件上限</span><strong>${bytes(fileLimit())}</strong></div><div class="aside-stat"><span>上传块大小</span><strong>${bytes(state.stats?.max_chunk_bytes||8*1024**2)}</strong></div><div class="aside-stat"><span>可用磁盘</span><strong>${bytes(state.stats?.free_disk_bytes)}</strong></div></div></section><section class="panel"><div class="aside-copy"><h3>导入前，确认这两件事</h3><p>编号类字段请选择「文本」，保留开头的零。日期字段支持 YYYY-MM-DD 和 YYYYMMDD。</p><p>仅为需要筛选的字段建立索引。首次导入完成索引和校验后，数据才会发布。</p><a class="btn sm" href="/assets/example.csv" download>${icon('download')} CSV 示例</a><a class="btn sm" href="/assets/example.xlsx" download>XLSX 示例</a><a class="btn sm" href="/assets/example.xls" download>XLS 示例</a></div></section></aside></div>`;}
function uploadPhaseLabel(){return ({idle:'等待上传',hashing:'正在计算文件校验值',uploading:'正在上传已校验的数据块',validating:'正在验证完整文件',ready:'上传完成，字段预览已就绪',paused:'上传已暂停，可继续',error:'上传中断，可重试'})[state.uploadPhase]||'等待上传';}
function mappingPanel(){const existing=state.datasets.find(d=>d.id===state.target);return `<section class="panel section-gap"><div class="panel-head"><span>02 / 配置数据集与字段</span><span class="pill neutral">预览 ${state.previewBusy?'切换工作表…':state.preview.rows.length+' 条'}</span></div><div class="panel-body">${state.preview.format!=='csv'?`<label class="form-label" for="excel-sheet">选择 Excel 工作表</label><select id="excel-sheet" ${state.previewBusy?'disabled':''}>${state.preview.sheets.map(name=>`<option value="${esc(name)}" ${state.preview.sheet===name?'selected':''}>${esc(name)}</option>`).join('')}</select><p class="help">一次导入一个工作表，首行作为列名。切换后请重新确认字段。</p>`:''}${state.preview.warnings?.length?`<div class="notice warning">${state.preview.warnings.map(w=>esc(errorText(w,state.preview.format==='csv'&&state.preview.row_mode==='single_line'))).join('；')}。${state.preview.format==='csv'?'这些行未显示在预览中；实际导入按下方的错误处理设置执行。':'可在 Excel 中重新计算并保存，或取消保留相应字段。'}</div>`:''}<div class="form-grid"><div><label class="form-label" for="target-dataset">导入目标</label><select id="target-dataset"><option value="">创建新数据集</option>${state.datasets.map(d=>`<option value="${d.id}" ${state.target===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div><div><label class="form-label" for="dataset-name">数据集名称</label><input class="input" id="dataset-name" value="${esc(existing?.name||state.datasetName)}" maxlength="100" ${existing?'disabled':''} placeholder="例如：库存数据"></div></div><p class="help">${existing?'已有数据集的字段定义保持不变。当前文件必须包含已配置的来源列。':'选择需要保留的列，并设置名称、类型和索引。未选择的列不会写入数据库。'}</p></div><div class="mapping-scroll"><table class="data-table mapping-table"><thead><tr><th>保留</th><th>${esc(state.preview.format.toUpperCase())} 来源列</th><th>字段名称</th><th>类型</th><th>索引</th></tr></thead><tbody>${state.mapping.map((m,i)=>`<tr><td><input type="checkbox" class="check" data-map="${i}" data-key="include" aria-label="保留 ${esc(m.source)}" ${m.include?'checked':''} ${existing?'disabled':''}></td><td title="${esc(m.source)}">${esc(m.source.length>26?m.source.slice(0,26)+'…':m.source)}</td><td><input class="input" data-map="${i}" data-key="name" value="${esc(m.name)}" maxlength="80" aria-label="${esc(m.source)} 字段名称" ${existing?'disabled':''}></td><td><select data-map="${i}" data-key="kind" aria-label="${esc(m.source)} 字段类型" ${existing?'disabled':''}>${[['text','文本'],['integer','整数'],['date','日期']].map(([v,n])=>`<option value="${v}" ${m.kind===v?'selected':''}>${n}</option>`).join('')}</select></td><td><input type="checkbox" class="check" data-map="${i}" data-key="indexed" aria-label="为 ${esc(m.source)} 建立索引" ${m.indexed?'checked':''} ${existing?'disabled':''}></td></tr>`).join('')}</tbody></table></div><div class="panel-body"><label class="form-label" for="on-error">遇到记录错误时</label><select id="on-error"><option value="fail" ${state.onError==='fail'?'selected':''}>停止导入，保留错误摘要</option><option value="skip" ${state.onError==='skip'?'selected':''}>跳过错误记录，继续导入</option></select><p class="help">${state.preview.format==='csv'&&state.rowMode==='single_line'?'逐行容错模式可拒绝列数、字段类型和引号错误的整行，再继续下一行。表头、编码或记录大小超限仍会停止。':'跳过适用于列数和字段错误；标准 CSV 的结构损坏仍会停止。'}</p><details style="margin-top:19px"><summary class="help" style="cursor:pointer">查看文件内容预览</summary><div class="table-wrap"><table class="data-table"><thead><tr>${state.preview.header.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${state.preview.rows.map(row=>`<tr>${row.map(v=>`<td title="${esc(v)}">${esc(String(v).slice(0,100))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></div><div class="mapping-footer"><small>最多 64 个字段 · 最多 16 个索引</small><button class="btn primary" data-action="start-import" ${state.previewBusy?'disabled':''}>${icon('play')} 开始后台导入</button></div></section>`;}
function queryFieldPriority(name){const key=String(name).normalize('NFKC').toLocaleLowerCase().replace(/[\s_-]+/g,'');if(key==='ctfid')return 0;if(['birthday','birthdate','dateofbirth','dob','birth'].includes(key)||key.includes('生日'))return 1;if(['address','addr'].includes(key)||key.endsWith('address')||key.endsWith('addr')||key.includes('地址')||key.includes('住址'))return 2;return 3;}
function commonQueryFieldHint(){const ds=state.datasets.find(d=>d.id===state.queryDataset);const fields=(ds?.columns||[]).filter(c=>queryFieldPriority(c.name)<3);return fields.length?`<p class="help" id="query-common-hint">常用字段优先显示：${fields.map(c=>esc(c.name)).join('、')}。其他已导入字段也可选。</p>`:'';}
function defaultQueryField(ds){return ds?.columns.find(c=>c.indexed)?.name||ds?.columns[0]?.name||'';}
function queryFieldHint(){const ds=state.datasets.find(d=>d.id===state.queryDataset);const fields=[...new Set(state.filters.map(f=>f.field))].filter(name=>ds?.columns.some(c=>c.name===name&&!c.indexed));return fields.length?`<p class="help" id="query-field-hint">${fields.map(name=>`「${esc(name)}」`).join('、')}未建立索引，数据量大时查询可能较慢。导入新数据时，可为常用查询字段勾选“索引”。</p>`:'';}
function filterRow(f,i){const ds=state.datasets.find(d=>d.id===state.queryDataset);const columns=[...(ds?.columns||[])].sort((a,b)=>queryFieldPriority(a.name)-queryFieldPriority(b.name)),column=columns.find(c=>c.name===f.field);return `<div class="filter-row" data-filter-row="${i}"><select data-filter="${i}" data-key="field" aria-label="筛选字段 ${i+1}">${columns.map(c=>`<option value="${esc(c.name)}" ${c.name===f.field?'selected':''}>${esc(c.name)}${c.indexed?'':'（未建索引）'}</option>`).join('')}</select><select data-filter="${i}" data-key="op" aria-label="匹配方式 ${i+1}">${[['eq','精确匹配'],['prefix','前缀匹配'],['gte','大于等于'],['lte','小于等于']].filter(([v])=>v!=='prefix'||column?.kind==='text').map(([v,n])=>`<option value="${v}" ${v===f.op?'selected':''}>${n}</option>`).join('')}</select><input class="input" data-filter="${i}" data-key="value" type="${column?.kind==='date'?'date':'text'}" value="${esc(f.value)}" maxlength="512" placeholder="${column?.kind==='integer'?'输入整数':'输入筛选值'}" aria-label="筛选值 ${i+1}"><button class="filter-remove" data-action="remove-filter" data-index="${i}" aria-label="移除筛选条件">${icon('close')}</button></div>`;}
function queryPage(){return header('数据查询','选择数据集和筛选条件，查看已发布的数据。','', 'QUERY / 数据筛选')+(!state.token?`<section class="panel">${guard()}</section>`:`<section class="panel query-panel"><div class="query-heading"><div><label class="form-label" for="query-dataset">选择数据集</label><select id="query-dataset"><option value="">请选择已发布的数据集</option>${state.datasets.map(d=>`<option value="${d.id}" ${state.queryDataset===d.id?'selected':''} ${d.active_version?'':'disabled'}>${esc(d.name)}${d.active_version?'':'（未发布）'}</option>`).join('')}</select></div><div class="query-hint">所有已导入字段都可筛选。<br>多个条件同时满足时才返回结果；留空可浏览记录。</div></div><div id="filters">${state.queryDataset?state.filters.map(filterRow).join(''):''}</div>${commonQueryFieldHint()}${queryFieldHint()}<div class="query-actions"><button class="btn sm" data-action="add-filter" ${!state.queryDataset||state.filters.length>=8?'disabled':''}>${icon('plus')} 添加条件</button><div class="actions"><button class="btn" data-action="clear-query">清空</button><button class="btn primary" data-action="run-query" ${!state.queryDataset||state.queryBusy?'disabled':''}>${state.queryBusy?'<span class="busy-mark"></span>':icon('search')} 查询数据</button></div></div></section><div class="section-title"><h2>查询结果</h2><div class="result-meta" id="result-meta">${state.result?`本页 ${num(state.result.rows.length)} 条 · ${Math.round(state.result.elapsed)}ms ${state.result.cache_hit?'<span class="pill">缓存命中</span>':''}`:'等待查询'}</div></div><section class="panel" id="query-results">${resultPanel()}</section>`);}
function resultPanel(){if(!state.result)return empty('开始一次查询','选择已发布的数据集，填写条件后点击「查询数据」。','','search');const r=state.result,ds=state.datasets.find(d=>d.id===state.querySnapshot?.dataset);if(!r.rows.length)return empty('没有找到匹配记录','请调整筛选值或减少条件后再次查询。','','search');return `<p class="help query-annotation-help">末尾显示当前账号保存在数据库中的标注和备注。</p>${state.queryDirty?'<div class="notice info" style="margin:15px 20px">筛选条件已修改，请重新查询以更新结果。</div>':''}<div class="table-wrap"><table class="data-table result-table"><thead><tr><th>来源记录</th>${(ds?.columns||[]).map(c=>`<th>${esc(c.name)}${c.indexed?icon('key'):''}</th>`).join('')}<th>标注状态</th><th>备注</th></tr></thead><tbody>${r.rows.map(row=>`<tr><td class="row-number">${num(row._row)}</td>${(ds?.columns||[]).map(c=>`<td title="${esc(row[c.name])}">${row[c.name]===null?'<span class="muted">空值</span>':esc(row[c.name])}</td>`).join('')}<td class="query-mark"><span class="pill ${r.annotations?.[String(row._row)]?.marked?'':'neutral'}">${r.annotations?.[String(row._row)]?.marked?'已标注':'未标注'}</span></td><td class="query-note" title="${esc(r.annotations?.[String(row._row)]?.note)}">${r.annotations?.[String(row._row)]?.note?esc(r.annotations[String(row._row)].note):'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>第 ${state.page+1} 页 · 每页最多 50 条</span><div class="actions"><button class="btn sm" data-action="query-prev" ${state.page===0||state.queryDirty||state.queryBusy?'disabled':''}>上一页</button><button class="btn sm" data-action="query-next" ${!r.next_cursor||state.queryDirty||state.queryBusy?'disabled':''}>下一页 ${icon('chevron')}</button></div></div>`;}
function settingsPage(){const s=state.stats,c=s?.cache;return header('系统设置','查看当前容量设置、查询缓存和访问状态。')+`<div class="system-grid"><section class="panel"><div class="panel-head">本地服务</div><div class="panel-body"><div class="setting-line"><span>服务地址</span><strong>${esc(location.origin)}</strong></div><div class="setting-line"><span>访问状态</span><strong>${state.token&&state.online?'已连接':'未连接'}</strong></div><div class="setting-line"><span>单文件上限</span><strong>${bytes(s?.max_upload_bytes)}</strong></div><div class="setting-line"><span>上传块大小</span><strong>${bytes(s?.max_chunk_bytes)}</strong></div><div class="setting-line"><span>可用磁盘空间</span><strong>${bytes(s?.free_disk_bytes)}</strong></div><div class="setting-line"><span>查询时间预算</span><strong>${s?s.query_timeout_seconds+' 秒':'—'}</strong></div><div class="setting-line"><span>同时查询上限</span><strong>${s?s.read_concurrency+' 个':'—'}</strong></div></div></section><section class="panel"><div class="panel-head">查询缓存</div><div class="panel-body"><div class="setting-line"><span>容量预算</span><strong>${bytes(c?.max_bytes)}</strong></div><div class="setting-line"><span>已使用（估算）</span><strong>${bytes(c?.accounted_bytes)}</strong></div><div class="setting-line"><span>缓存结果</span><strong>${c?num(c.entries)+' 组':'—'}</strong></div><div class="setting-line"><span>命中 / 未命中</span><strong>${c?num(c.hits)+' / '+num(c.misses):'—'}</strong></div><p class="help">缓存按数据版本区分。新版本发布后，查询会使用新的结果。</p></div></section><section class="panel"><div class="panel-head">登录状态</div><div class="panel-body"><p class="help" style="margin:0 0 20px">当前以 ${esc(state.user?.username)} 登录。退出登录后返回登录页面。</p><div class="actions"><button class="btn" data-action="login">${icon('key')} 切换账号</button>${state.token?'<button class="btn danger" data-action="disconnect">退出登录</button>':''}</div></div></section></div>`+workbench.userPanel();}
function cleanupNotice(){const pending=state.user?.role==='admin'&&state.stats?.pending_file_cleanup;return pending?`<div class="notice warning" id="file-cleanup-notice">还有 ${num(pending)} 个本地文件待清理，系统每 30 秒自动重试。请关闭正在占用相关文件的软件。</div>`:'';}
function syncCleanupNotice(){const notice=$('#file-cleanup-notice'),html=cleanupNotice();if(notice)notice.outerHTML=html;else if(html)$('#content')?.insertAdjacentHTML('afterbegin',html);}
function render(){if(!state.token||!state.user){openLogin();return;}if(!$('#content'))return;const pages={overview,datasets,import:importPage,jobs,query:queryPage,extract:workbench.extractPage,settings:settingsPage};$('#content').innerHTML=cleanupNotice()+pages[state.view]();updateChrome();}
function showDialog(title,body){const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="dialog-close" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function openLogin(message=''){disconnect(false,message);}
function disconnect(notify=true,message=''){authGeneration++;previewGeneration++;workbench.reset();$('#toasts').replaceChildren();state.user=null;state.uploadController?.abort();state.hashWorker?.terminate();state.uploadBusy=false;state.token='';state.upload=null;state.file=null;state.uploadPhase='idle';sessionStorage.removeItem('csvhub.upload');sessionStorage.removeItem('csvhub.token');state.online=false;state.datasets=[];state.jobs=[];state.details.clear();state.stats=null;state.result=null;state.querySnapshot=null;state.queryDataset='';state.filters=[blankFilter()];state.preview=null;state.mapping=[];if($('#dialog').open)$('#dialog').close();$('#app').replaceChildren();if(message||notify)sessionStorage.setItem('csvhub.login-message',message||'已退出登录。');location.replace('/login');}
async function refresh(){
  if(!state.token)return;
  if(state.refreshing?.generation===authGeneration)return state.refreshing.promise;
  const generation=authGeneration;
  const pendingRefresh={generation,promise:null};
  pendingRefresh.promise=(async()=>{
    const user=await api('/auth/me');if(generation!==authGeneration)throw new DOMException('Session changed','AbortError');state.user=user;if(user.role==='user'&&!['overview','extract','query'].includes(state.view))setView('overview');const [ds,jobs,stats]=await Promise.all([api('/datasets?limit=200'),user.role==='admin'?api('/jobs?limit=200'):Promise.resolve({items:[]}),user.role==='admin'?api('/stats'):Promise.resolve(null),workbench.loadSummary(),user.role==='admin'?workbench.loadUsers():Promise.resolve()]);
    if(generation!==authGeneration)throw new DOMException('Session changed','AbortError');
    state.datasets=ds.items;state.jobs=jobs.items;state.stats=stats;
    for(const id of state.details.keys())if(!ds.items.some(d=>d.id===id))state.details.delete(id);
    if(state.queryDataset&&!ds.items.some(d=>d.id===state.queryDataset))setQueryDataset('');
    workbench.discardMissingDatasets();
    const completed=new Map();
    for(const job of jobs.items)if(job.status==='completed'&&!completed.has(job.dataset_id))completed.set(job.dataset_id,job.id);
    const pending=ds.items.filter(d=>!state.details.has(d.id)||state.details.get(d.id).active_version!==d.active_version||(completed.has(d.id)&&completed.get(d.id)!==d.active_version));
    let index=0;
    await Promise.all(Array.from({length:Math.min(4,pending.length)},async()=>{
      while(index<pending.length){const d=pending[index++];const detail=await api('/datasets/'+d.id);state.details.set(d.id,detail);d.active_version=detail.active_version;}
    }));
    if(generation!==authGeneration)throw new DOMException('Session changed','AbortError');
    if(state.view==='extract')workbench.updateDatasets();
    if(state.view==='query'&&$('#query-dataset'))$('#query-dataset').innerHTML=`<option value="">请选择已发布的数据集</option>${state.datasets.map(d=>`<option value="${d.id}" ${state.queryDataset===d.id?'selected':''} ${d.active_version?'':'disabled'}>${esc(d.name)}${d.active_version?'':'（未发布）'}</option>`).join('')}`;
    if(state.view==='datasets')$('#dataset-list').innerHTML=datasetTable(state.datasets.filter(d=>d.name.toLowerCase().includes(state.search.toLowerCase())));
    else if(state.view==='jobs')$('#job-list').innerHTML=jobTable(state.jobs.filter(j=>(jobName(j)+j.id).toLowerCase().includes(state.jobSearch.toLowerCase())));
    else if(state.view==='overview'||(state.view==='settings'&&!document.activeElement?.closest('form')))render();
    updateChrome();syncCleanupNotice();
  })().finally(()=>{if(state.refreshing===pendingRefresh)state.refreshing=null;});
  state.refreshing=pendingRefresh;
  return pendingRefresh.promise;
}
async function poll(){try{if(state.token&&document.visibilityState==='visible')await refresh();}catch{updateChrome();}const active=state.jobs.some(j=>activeStatuses.includes(j.status));setTimeout(poll,active?4000:20000);}
function selectFile(file){if(!file)return;if(state.uploadBusy){toast('请先暂停正在进行的上传。');return;}if(file.size===0){toast('这个文件是空的。','error');return;}if(file.size>(state.stats?.max_upload_bytes||20*1024**3)){toast('文件超出当前单文件大小限制。','error');return;}if(!/\.(csv|xlsx|xls)$/i.test(file.name)){toast('请选择 CSV、XLS 或 XLSX 文件。','error');return;}if(/\.xls$/i.test(file.name)&&file.size>(state.stats?.max_xls_bytes||128*1024**2)){toast('XLS 超出当前 '+bytes(state.stats?.max_xls_bytes||128*1024**2)+' 限制，请使用 XLSX 或 CSV。','error');return;}previewGeneration++;state.previewBusy=false;state.sheet=null;state.file=file;state.preview=null;state.mapping=[];state.uploadPhase='idle';state.uploadProgress=0;state.datasetName=file.name.replace(/\.(csv|xlsx|xls)$/i,'').slice(0,100);render();}
function uploadProgress(phase,percent){state.uploadPhase=phase;state.uploadProgress=Math.max(0,Math.min(100,percent));const text=$('#upload-stage');if(text)text.textContent=uploadPhaseLabel();if($('#upload-percent'))$('#upload-percent').textContent=Math.round(state.uploadProgress)+'%';if($('#upload-bar'))$('#upload-bar').style.width=state.uploadProgress+'%';}
function hashFile(file,signal){return new Promise((resolve,reject)=>{const worker=new Worker('/assets/hash-worker.js',{type:'module'});state.hashWorker=worker;const abort=()=>{worker.terminate();reject(new DOMException('Upload paused','AbortError'));};signal.addEventListener('abort',abort,{once:true});worker.onerror=()=>{signal.removeEventListener('abort',abort);worker.terminate();reject(new Error('文件校验线程无法运行，请使用新版浏览器。'));};worker.onmessage=({data})=>{if(data.type==='progress')uploadProgress('hashing',data.bytes/file.size*100);else{signal.removeEventListener('abort',abort);worker.terminate();state.hashWorker=null;data.type==='done'?resolve(data.sha256):reject(new Error('文件校验失败。'));}};worker.postMessage({file});});}
function saveUpload(){sessionStorage.setItem('csvhub.upload',JSON.stringify(state.upload));}
async function uploadFile(){
  if(!state.token){openLogin();return;}if(!state.file||state.uploadBusy)return;if(state.uploadPhase==='ready'){await previewFile();return;}
  state.uploadBusy=true;state.uploadController=new AbortController();const signal=state.uploadController.signal;render();
  try{
    const sha256=await hashFile(state.file,signal);let upload=null;
    if(state.upload?.sha256===sha256&&state.upload.size===state.file.size&&state.upload.filename.split('.').pop().toLowerCase()===fileFormat()){try{upload=await api('/uploads/'+state.upload.id,{signal});}catch(error){if(error.status!==404)throw error;}}
    if(!upload||upload.state==='invalid')upload=await api('/uploads',{method:'POST',json:{filename:state.file.name,size:state.file.size,sha256},signal});
    state.upload={id:upload.id,sha256,size:state.file.size,filename:state.file.name};saveUpload();
    if(upload.state==='uploading'){
      const chunkSize=state.stats?.max_chunk_bytes||8*1024**2;
      for(let offset=upload.received;offset<state.file.size;){
        if(signal.aborted)throw new DOMException('Paused','AbortError');
        uploadProgress('uploading',offset/state.file.size*100);
        const chunk=await state.file.slice(offset,offset+chunkSize).arrayBuffer();
        const hash=await chunkDigest(chunk);
        try{upload=await api(`/uploads/${upload.id}/chunks?offset=${offset}`,{method:'PUT',body:chunk,headers:{'X-Chunk-SHA256':hash,'Content-Type':'application/octet-stream'},signal});offset=upload.received;}
        catch(error){if(error.status===409){const durable=await api('/uploads/'+upload.id,{signal});if(durable.received>offset&&durable.received<=state.file.size){upload=durable;offset=durable.received;continue;}}throw error;}
      }
    }
    uploadProgress('validating',100);if(upload.state!=='ready')await api('/uploads/'+upload.id+'/complete',{method:'POST',signal});
    await previewFile();toast('上传和校验已完成，请确认导入字段。','success');
  }catch(error){uploadProgress(error.name==='AbortError'?'paused':'error',state.uploadProgress);if(error.name!=='AbortError')toast(error.message,'error');}
  finally{state.uploadBusy=false;state.uploadController=null;if(state.view==='import')render();}
}
function resetMapping(){const existing=state.datasets.find(d=>d.id===state.target);state.mapping=existing?existing.columns.map(c=>({...c,include:true})):state.preview.header.map((source,i)=>({source,name:source.slice(0,80),kind:'text',indexed:i<4,nullable:true,trim:false,include:i<64}));}
async function previewFile(){
  const generation=++previewGeneration;state.previewBusy=true;if(state.view==='import')render();
  try{
    const query=new URLSearchParams({encoding:state.encoding,delimiter:state.delimiter,row_mode:fileFormat()==='csv'?state.rowMode:'standard'});
    if(state.sheet!==null)query.set('sheet',state.sheet);
    const preview=await api(`/uploads/${state.upload.id}/preview?${query}`);
    if(generation!==previewGeneration)return;
    if(!preview.header.length||preview.header.length>1024)throw new Error('当前页面支持 1～1024 个来源列。');
    if(new Set(preview.header).size!==preview.header.length||preview.header.some(c=>!c||c.length>200))throw new Error('表头必须唯一、非空，且每个列名不超过 200 个字符。');
    state.preview=preview;state.sheet=preview.sheet;state.uploadPhase='ready';state.uploadProgress=100;resetMapping();
  }catch(error){if(generation===previewGeneration)state.preview=null;throw error;}
  finally{if(generation===previewGeneration){state.previewBusy=false;if(state.view==='import')render();}}
}
async function startImport(){if(!state.token){openLogin();return;}if(!state.upload||!state.preview||state.previewBusy)return;let target=state.target;const existing=state.datasets.find(d=>d.id===target);const columns=state.mapping.filter(m=>m.include).map(({include,...m})=>m);if(!columns.length||columns.length>64)throw new Error('请选择 1～64 个导入字段。');if(columns.filter(c=>c.indexed).length>16)throw new Error('最多为 16 个字段建立索引。');if(new Set(columns.map(c=>c.name)).size!==columns.length||columns.some(c=>!c.name.trim()||c.name==='_row'))throw new Error('字段名称必须唯一且非空，不能使用保留名称 _row。');if(existing&&existing.columns.some(c=>!state.preview.header.includes(c.source)))throw new Error('当前文件缺少已有数据集配置的来源列。');if(!target){if(!state.datasetName.trim())throw new Error('请填写数据集名称。');const dataset=await api('/datasets',{method:'POST',json:{name:state.datasetName.trim(),columns}});target=dataset.id;state.target=target;}
  const job=await api(`/datasets/${target}/imports`,{method:'POST',json:{upload_id:state.upload.id,sheet:state.preview.sheet,encoding:state.encoding,delimiter:state.delimiter,on_error:state.onError,row_mode:state.preview.format==='csv'?state.rowMode:'standard'}});toast('导入任务已提交，编号 '+job.id.slice(0,8)+'。','success');await refresh();setView('jobs');
}
function setQueryDataset(id){state.queryDataset=id;const ds=state.datasets.find(d=>d.id===id);state.filters=[{field:defaultQueryField(ds),op:'eq',value:''}];state.result=null;state.querySnapshot=null;state.pageCursors=[null];state.page=0;state.queryDirty=false;render();}
function reflectQueryAnnotation(version,rowNo,annotation){if(state.result?.version!==version||!state.result.rows.some(row=>row._row===rowNo))return;state.result.annotations={...state.result.annotations,[String(rowNo)]:{marked:annotation.marked,note:annotation.note,revision:annotation.revision,updated_at:null}};if(state.view==='query'&&$('#query-results'))$('#query-results').innerHTML=resultPanel();}
function markQueryDirty(){state.queryDirty=!!state.result;if($('#query-results'))$('#query-results').innerHTML=resultPanel();}
async function runQuery(direction='new'){if(state.queryBusy||!state.queryDataset)return;let snapshot,page=state.page;
  if(direction==='new'){snapshot={dataset:state.queryDataset,filters:state.filters.filter(f=>f.value!=='').map(f=>({...f})),limit:50};page=0;state.pageCursors=[null];}
  else {snapshot=state.querySnapshot;if(!snapshot)return;page=direction==='next'?page+1:page-1;if(page<0)return;if(direction==='next')state.pageCursors[page]=state.result.next_cursor;}
  state.queryBusy=true;render();const started=performance.now();
  try{await workbench.flush();const result=await api(`/datasets/${snapshot.dataset}/query`,{method:'POST',json:{filters:snapshot.filters,limit:snapshot.limit,cursor:state.pageCursors[page]}});state.result={...result,elapsed:performance.now()-started};state.querySnapshot=snapshot;state.page=page;state.queryDirty=false;}
  finally{state.queryBusy=false;render();}
}
async function jobAction(action,id){if(state.jobBusy.has(id))return;state.jobBusy.add(id);try{const job=state.jobs.find(j=>j.id===id);if(['retry','retry-lines'].includes(action))await api(`/datasets/${job.dataset_id}/imports`,{method:'POST',json:{upload_id:job.upload_id,...job.options,...(action==='retry-lines'?{row_mode:'single_line',on_error:'skip'}:{})}});else await api(`/jobs/${id}/${action}`,{method:'POST'});toast(action==='cancel'?'已请求取消任务。':action==='pause'?'已请求暂停任务。':action==='resume'?'任务已恢复排队。':'新导入任务已创建。','success');await refresh();}finally{state.jobBusy.delete(id);if(state.view==='jobs')render();}}
async function showVersions(id){const d=state.datasets.find(x=>x.id===id);const data=await api(`/datasets/${id}/versions`);showDialog('数据版本',`<p>${esc(d?.name)} · 已发布版本会保留在本机。</p>${data.items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>版本</th><th>记录数</th><th>发布时间</th></tr></thead><tbody>${data.items.map(v=>`<tr><td>${v.id.slice(0,8)} ${v.id===d.active_version?'<span class="pill">当前</span>':''}</td><td>${num(v.accepted)}</td><td>${date(v.published_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p>还没有已发布的版本。</p>'}`);}
async function showErrors(id){const [job,errors]=await Promise.all([api('/jobs/'+id),api('/jobs/'+id+'/errors')]);showDialog('导入任务详情',`<p>${esc(jobName(job))} · ${badge(job)}<br>处理 ${num(job.processed)} 条，接受 ${num(job.accepted)} 条，拒绝 ${num(job.rejected)} 条。</p><p class="help">记录格式：${job.options.row_mode==='single_line'?'一行一条记录（逐行容错）':'标准格式'}。错误处理：${job.options.on_error==='skip'?'跳过错误记录，继续导入':'遇到记录错误时停止导入'}。计数为已提交记录数，来源记录序号与文件行号在含换行字段时不同。</p>${job.options.on_error==='skip'&&job.rejected?`<div class="notice info">已跳过 ${num(job.rejected)} 条列数、字段或 CSV 格式错误记录。${job.status==='failed'?'任务因下方另一项错误停止。':'这些记录不会写入数据集。'}</div>`:''}${job.error?`<div class="notice error">${esc(errorText(job.error))}</div>`:''}${errors.items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>来源记录序号</th><th>错误摘要</th></tr></thead><tbody>${errors.items.map(e=>`<tr><td>${num(e.record)}</td><td style="white-space:normal">${esc(errorText(e.reason,job.options.row_mode==='single_line'))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">当前没有已提交的错误记录摘要。</p>'}${job.status==='queued'?'<div class="notice info">任务还在排队。若长时间未开始，请确认导入执行器正在运行。</div>':''}`);}
function openDelete(kind,id){const item=kind==='dataset'?state.datasets.find(d=>d.id===id):state.jobs.find(j=>j.id===id);if(!item)return;const name=kind==='dataset'?item.name:jobName(item)+' · '+id.slice(0,8);const scope=kind==='dataset'?'删除该数据集的全部版本、导入任务、提取批次、标注和备注，并清理本系统保存的原始 CSV / Excel 上传文件及数据库文件。':'删除任务记录及它独占的原始上传文件。已发布的数据继续保留；失败或取消任务产生的临时数据库会清理。';showDialog(kind==='dataset'?'删除数据集':'删除导入任务',`<p>确定删除「${esc(name)}」？</p><div class="notice warning">${scope}</div><p class="help">被其他任务或数据集使用的原始文件会保留。此操作无法撤销。原始文件指本系统保存的上传副本。</p><p class="error-text" id="delete-error" role="alert"></p><div class="dialog-footer"><button class="btn" data-action="close-dialog">取消</button><button class="btn danger" data-action="confirm-delete" data-kind="${kind}" data-id="${id}">确认删除</button></div>`);}
async function confirmDelete(button){const kind=button.dataset.kind,id=button.dataset.id;button.disabled=true;$('#delete-error').textContent='';try{if(kind==='dataset')await workbench.flush();const result=await api(`/${kind==='dataset'?'datasets':'jobs'}/${id}`,{method:'DELETE'});$('#dialog').close();if(state.refreshing)await state.refreshing.promise.catch(()=>{});if(kind==='dataset'){state.details.delete(id);if(state.target===id)state.target='';if(state.queryDataset===id)setQueryDataset('');}if(state.upload){try{await api('/uploads/'+state.upload.id);}catch(error){if(error.status===404){previewGeneration++;state.upload=null;state.preview=null;state.mapping=[];state.uploadPhase='idle';sessionStorage.removeItem('csvhub.upload');}else throw error;}}await refresh();render();toast(result.cleanup_pending?'记录已删除，部分本地文件仍待清理，系统会自动重试。':'已删除，本地独占文件已清理。',result.cleanup_pending?'warning':'success');if(result.retained_uploads)toast('部分原始文件仍被其他任务或数据集使用，已保留。');}catch(error){if($('#dialog').open&&$('#delete-error'))$('#delete-error').textContent=error.message;else throw error;}finally{if(button.isConnected)button.disabled=false;}}
document.addEventListener('click',async(event)=>{
  if(event.target.closest('#dropzone')){$('#file-input')?.click();return;}
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,id=button.dataset.id;
  try{switch(action){
    case 'menu':$('.app').classList.toggle('menu-open');break;
    case 'close-dialog':$('#dialog').close();break;case 'login':case 'disconnect':try{await workbench.flush();await api('/auth/logout',{method:'POST'});}finally{disconnect();}break;
    case 'new-import':state.target='';if(state.preview)resetMapping();setView('import');break;
    case 'dataset-import':state.target=id;if(state.preview)resetMapping();setView('import');break;
    case 'dataset-query':setView('query');setQueryDataset(id);break;
    case 'dataset-delete':openDelete('dataset',id);break;
    case 'job-delete':openDelete('job',id);break;
    case 'confirm-delete':await confirmDelete(button);break;
    case 'refresh':button.disabled=true;await refresh();toast('已更新服务数据。');break;
    case 'versions':await showVersions(id);break;
    case 'choose-file':$('#file-input')?.click();break;
    case 'upload-start':await uploadFile();break;
    case 'upload-stop':state.uploadController?.abort();break;
    case 'start-import':button.disabled=true;await startImport();break;
    case 'add-filter':{const ds=state.datasets.find(d=>d.id===state.queryDataset);state.filters.push({field:defaultQueryField(ds),op:'eq',value:''});markQueryDirty();render();break;}
    case 'remove-filter':state.filters.splice(Number(button.dataset.index),1);markQueryDirty();render();break;
    case 'clear-query':setQueryDataset(state.queryDataset);break;
    case 'run-query':await runQuery();break;case 'query-next':await runQuery('next');break;case 'query-prev':await runQuery('prev');break;
    case 'job-retry-lines':await jobAction('retry-lines',id);break;
    case 'job-errors':await showErrors(id);break;
    default:if(action.startsWith('job-'))await jobAction(action.slice(4),id);
  }}catch(error){if(error.name!=='AbortError')toast(error.message,'error');}finally{if(button.isConnected)button.disabled=false;}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='dataset-search'){state.search=el.value;$('#dataset-list').innerHTML=datasetTable(state.datasets.filter(d=>d.name.toLowerCase().includes(state.search.toLowerCase())));}else if(el.id==='job-search'){state.jobSearch=el.value;$('#job-list').innerHTML=jobTable(state.jobs.filter(j=>(jobName(j)+j.id).toLowerCase().includes(state.jobSearch.toLowerCase())));}else if(el.id==='dataset-name')state.datasetName=el.value;else if(el.dataset.map!==undefined&&el.dataset.key==='name')state.mapping[Number(el.dataset.map)].name=el.value;else if(el.dataset.filter!==undefined&&el.dataset.key==='value'){state.filters[Number(el.dataset.filter)].value=el.value;markQueryDirty();}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='file-input')selectFile(el.files[0]);else if(el.id==='excel-sheet'){state.sheet=el.value;await previewFile();}else if(['encoding','delimiter'].includes(el.id)){state[el.id]=el.value;if(state.uploadPhase==='ready')await previewFile();}else if(el.id==='csv-row-mode'){state.rowMode=el.value;if(el.value==='single_line')state.onError='skip';if(state.upload&&['ready','validating','error'].includes(state.uploadPhase))await previewFile();else render();}else if(el.id==='on-error')state.onError=el.value;else if(el.id==='target-dataset'){state.target=el.value;resetMapping();render();}else if(el.id==='query-dataset')setQueryDataset(el.value);else if(el.dataset.map!==undefined){const m=state.mapping[Number(el.dataset.map)];m[el.dataset.key]=el.type==='checkbox'?el.checked:el.value;}else if(el.dataset.filter!==undefined){if(el.dataset.key==='value')return;const f=state.filters[Number(el.dataset.filter)];f[el.dataset.key]=el.value;if(el.dataset.key==='field'){f.op='eq';f.value='';}markQueryDirty();render();}}catch(error){toast(error.message,'error');}});
document.addEventListener('keydown',event=>{if(event.target.id==='dropzone'&&(event.key==='Enter'||event.key===' ')){event.preventDefault();$('#file-input').click();}if(event.key==='Enter'&&event.target.dataset.filter!==undefined){event.preventDefault();runQuery().catch(e=>toast(e.message,'error'));}});
document.addEventListener('dragover',event=>{const zone=event.target.closest('#dropzone');if(zone){event.preventDefault();zone.classList.add('drag');}});
document.addEventListener('dragleave',event=>event.target.closest('#dropzone')?.classList.remove('drag'));
document.addEventListener('drop',event=>{const zone=event.target.closest('#dropzone');if(zone){event.preventDefault();zone.classList.remove('drag');selectFile(event.dataTransfer.files[0]);}});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1),false));
const workbench=createWorkbench({state,api,esc,num,date,icon,header,empty,metric,toast,render,showDialog,refresh,reflectQueryAnnotation});
async function startWorkspace(){
  if(!state.token){openLogin();return;}
  try{await refresh();if(!state.token||!state.user)return;shell();poll();}
  catch(error){if(error.name!=='AbortError'&&state.token)openLogin(error.status===401?'登录已失效，请重新登录。':'暂时无法进入工作台，请重新登录或稍后重试。');}
}
window.addEventListener('pageshow',event=>{if(event.persisted){$('#app').replaceChildren();location.reload();}});
startWorkspace();
